insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:architect','AU','architect','Architect','OSCA','2024 v1.0','2411','AUD',true,'State and territory Architects Registration Boards; AACA accreditation and migration assessment functions','https://aaca.org.au/migration-assessments/','profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:architect','2026-05-01',19300,null,null,null,1852,19,34,40,44,455.66667,'2026-05-01',13.16,10.26,19.20,0,0,5,0,10,0,5,10,1,31,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','Current OSCA 241131 Architect is an exact canonical occupation and requires registration or licensing to practise under the architect title.','labour_scope','JSA legacy ANZSCO 232111 provides 19,300 workers, 19% part-time share, 34% female share, median age 40 and 44 average full-time hours. Reviewed median earnings remain unavailable.','vacancy_scope','Broader ANZSCO 2321 vacancies were 455.66667 in May 2026 versus 402.66667 in May 2025, about +13.16% year on year. Because the vacancy series is broader, vacancy intensity and trend receive zero credit.','projection_scope','Broader ANZSCO 2321 projections are +10.26% to 2030 and +19.20% to 2035; partial growth credit only.','shortage_note','JSA 2025 OSL records current OSCA 241131 Architect as No Shortage nationally.','visa_basis','The reviewed current migration ingest records OSCA 241131 / legacy ANZSCO 232111 Architect as eligible on the Core Skills Occupation List. AACA provides the relevant migration skills assessment function.','entry_level_basis','RMIT Master of Architecture 060829B and UNSW Master of Architecture 061906G are current two-year professional postgraduate routes following appropriate prior architecture study.','entry_burden_basis','Professional practice requires an accredited architecture pathway, practical experience, the Architectural Practice Examination and state or territory registration. Migration assessment is separate from registration.','score_note','Full current migration credit is supported, but shortage and salary remain zero; broader vacancy data are contextual and broader projections receive partial growth credit.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
